import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"Forms and human collaboration","description":"","frontmatter":{"title":"Forms and human collaboration"},"headers":[],"relativePath":"guide/forms.md","filePath":"guide/forms.md"}'),s={name:"guide/forms.md"};function i(n,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="forms-and-human-collaboration" tabindex="-1">Forms and human collaboration <a class="header-anchor" href="#forms-and-human-collaboration" aria-label="Permalink to &quot;Forms and human collaboration&quot;">​</a></h1><p>Forms collect input; form tasks and approvals pause a workflow for human action. They work together but are different nodes.</p><h2 id="design-a-form" tabindex="-1">Design a form <a class="header-anchor" href="#design-a-form" aria-label="Permalink to &quot;Design a form&quot;">​</a></h2><ol><li>On the <strong>Forms</strong> page, select <strong>New</strong> and add fields in the designer.</li><li>Configure labels, input types and required-field rules, then save.</li><li>Test fields, validation and submission with non-sensitive test data.</li></ol><h2 id="three-ways-to-use-forms" tabindex="-1">Three ways to use forms <a class="header-anchor" href="#three-ways-to-use-forms" aria-label="Permalink to &quot;Three ways to use forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Behavior</th></tr></thead><tbody><tr><td><a href="./../trigger_form.html">Form trigger</a></td><td>A submission starts the associated workflow</td></tr><tr><td><a href="./../form_task.html">Form task</a></td><td>The running flow creates tasks for members and continues when the configured conditions are met</td></tr><tr><td><a href="./../approval.html">Approval</a></td><td>The flow waits for a decision and follows the approved, rejected or timed-out path</td></tr></tbody></table><h2 id="example-collect-→-process-→-review" tabindex="-1">Example: collect → process → review <a class="header-anchor" href="#example-collect-→-process-→-review" aria-label="Permalink to &quot;Example: collect → process → review&quot;">​</a></h2><p>This example uses only forms, a data table and a workflow; it does not require business-page publishing.</p><ol><li>Create a <strong>Requests</strong> table with fields such as request content and status.</li><li>Create a <strong>Request submission</strong> form to collect content.</li><li>Create a workflow with a form trigger, select the form and configure allowed members as needed.</li><li>Add an <a href="./../data_table_insert.html">insert node</a>, map the submitted content to the table and set the initial status to pending.</li><li>For additional information, add a form task with the form and members. For a decision, use an approval node instead.</li><li>Update status in the appropriate branch and configure an explicit output.</li><li>Save and submit a test form. Inspect its trigger data in execution records; process pending tasks under <strong>User tasks</strong> when applicable.</li><li>Check the final table record and workflow output.</li></ol><p>Form tasks follow their configured any/all-sign behavior; see the node reference. A successful submission does not imply approval or full workflow completion.</p><h2 id="access-and-privacy" tabindex="-1">Access and privacy <a class="header-anchor" href="#access-and-privacy" aria-label="Permalink to &quot;Access and privacy&quot;">​</a></h2><p>Form-trigger members determine who can submit. Verify authentication and access boundaries before publishing a submission URL. Submitted content flows into execution records and subsequent tools, so inspect screenshots, logs and shared links for sensitive data.</p>',12)])])}const f=a(s,[["render",i]]);export{u as __pageData,f as default};
